/// <reference path="./sigApi.AlarmConfig.d.ts" />
/// <reference path="./sigApi.ApiBase.d.ts" />

declare namespace SigApi {
    interface ApiAlarmConfig extends ApiBase {
        /**
         * @param {number} varNo the datapoint id of the alarm
         * @param {number} [group=undefined]
         * @returns {number}
         */
        getAlarmConfigId(varNo: number, group?: number): number
        /**
         * @param {number} alarmConfigId 
         * @returns {AlarmConfig}
         */
        getAlarmConfig(alarmConfigId: number): AlarmConfig | null
        /**
         * @returns {AlarmConfig[]}
         */
        getAlarmConfigList(): AlarmConfig[]
        /**
         * Function to check if parameter object is a instanceof AlarmConfig.
         * This function can be used without importing the type AlarmConfig to be used with the instanceof operator.
         * @param {*} object Any object to type check
         * @returns {boolean} Returns true if parameter object is instanceof AlarmConfig, else false
         */
        instanceofAlarmConfig(object: any): boolean
    }
}
